def fill_site_and_project(apps, schema_editor):
    """Every existing schedule was per project: its home is that project's
    site, and every section and line belongs to that project."""
    ProcurementSchedule = apps.get_model("core", "ProcurementSchedule")
    ScheduleSection = apps.get_model("core", "ScheduleSection")
    ScheduleLine = apps.get_model("core", "ScheduleLine")
    for s in ProcurementSchedule.objects.select_related("document", "project"):
        s.site_id = s.document.site_id
        s.save(update_fields=["site"])
        if s.project_id:
            ScheduleSection.objects.filter(schedule=s).update(
                project_id=s.project_id)
            ScheduleLine.objects.filter(schedule=s).update(
                project_id=s.project_id)


